paragraph.math:
$$\begin{array}{l}
  {{{\iiint\limits_{B}e^{{({x^{2} + y^{2} + z^{2}})}^{3 \slash 2}}}\mathit{dV}} = {\int_{0}^{\pi}\int_{0}^{2\pi}\int_{0}^{1}e^{{(\rho^{2})}^{3 \slash 2}}\rho^{2}}{\sin\phi d\rho d\theta d\phi}} \\
  {\phantom{{\iiint\limits_{B}e^{{({x^{2} + y^{2} + z^{2}})}^{3 \slash 2}}}\mathit{dV}} = {\int_{0}^{\pi}\sin\phi d\phi\int_{0}^{2\pi}d\theta\int_{0}^{1}\rho^{2}e^{\rho^{3}}d\rho}} \\
  {\phantom{{\iiint\limits_{B}e^{{({x^{2} + y^{2} + z^{2}})}^{3 \slash 2}}}\mathit{dV}} = {\left\lbrack {- \cos\phi} \right\rbrack_{0}^{\pi}{({2\pi})}\left\lbrack {\frac{1}{3}e^{\rho^{3}}} \right\rbrack_{0}^{1} = \frac{4}{3}\pi{({e - 1})}}}
  \end{array}$$
